target.css:
:root {
  --ink: #20362b;
  --muted: #6c7b70;
  --paper: #fffef9;
  --line: #d9e2d7;
  --leaf: #2d7a4e;
  --leaf-soft: #e4f2e8;
  --sun: #e8aa3d;
  --sun-soft: #fff4d9;
  --rose: #b65b57;
  --rose-soft: #fae9e7;
}

.irrigation-console {
  box-sizing: border-box;
  width: 500px;
  padding: 16px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.console-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-bottom: 13px;
  border-bottom: 1px solid var(--line);
}

.title-block {
  flex: 1;
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.07em;
  line-height: 1;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: 21px;
  font-weight: 750;
  letter-spacing: -0.04em;
  line-height: 1.1;
}

.live-badge {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 6px 8px;
  color: var(--leaf);
  background: var(--leaf-soft);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}

.live-dot {
  width: 6px;
  height: 6px;
  background: var(--leaf);
  border-radius: 50%;
}

.sync-button,
.details-button {
  border: 0;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

.sync-button {
  padding: 7px 10px;
  color: var(--paper);
  background: var(--leaf);
  border-radius: 8px;
  font-size: 12px;
}

.dashboard-grid {
  display: grid;
  grid-template-columns: 168px 1fr;
  gap: 12px;
  padding: 14px 0;
}

.moisture-card {
  box-sizing: border-box;
  min-height: 118px;
  padding: 13px;
  background: var(--sun-soft);
  border: 1px solid var(--sun);
  border-radius: 13px;
}

.card-heading,
.zones-heading,
.zone-row {
  display: flex;
  align-items: center;
}

.card-heading {
  justify-content: space-between;
  gap: 8px;
  font-size: 12px;
  font-weight: 700;
}

.card-heading strong {
  color: var(--leaf);
  font-size: 20px;
  letter-spacing: -0.05em;
}

.moisture-meter {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 4px;
  margin: 13px 0 9px;
}

.meter-bar {
  height: 8px;
  background: var(--paper);
  border: 1px solid var(--sun);
  border-radius: 999px;
}

.meter-bar.filled {
  background: var(--leaf);
  border-color: var(--leaf);
}

.moisture-card p {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.25;
}

.zones-panel {
  padding: 2px 0;
}

.zones-heading {
  justify-content: space-between;
  margin-bottom: 6px;
  font-size: 12px;
  font-weight: 750;
}

.zone-count {
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
}

.zone-list {
  display: grid;
  gap: 5px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.zone-row {
  gap: 8px;
  min-height: 24px;
  padding: 4px 7px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 7px;
  font-size: 11px;
}

.zone-number {
  color: var(--muted);
  font-weight: 700;
}

.zone-name {
  flex: 1;
  font-weight: 650;
}

.zone-status {
  padding: 3px 6px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 750;
}

.zone-status.running {
  color: var(--leaf);
  background: var(--leaf-soft);
}

.zone-status.queued {
  color: var(--sun);
  background: var(--sun-soft);
}

.zone-status.paused {
  color: var(--rose);
  background: var(--rose-soft);
}

.zone-row time {
  color: var(--muted);
  font-weight: 650;
}

.schedule-footer {
  display: flex;
  align-items: center;
  gap: 9px;
  padding-top: 11px;
  border-top: 1px solid var(--line);
}

.calendar-mark {
  display: grid;
  width: 29px;
  height: 29px;
  place-items: center;
  color: var(--paper);
  background: var(--ink);
  border-radius: 8px;
  font-size: 12px;
  font-weight: 750;
}

.schedule-footer p {
  display: grid;
  gap: 2px;
  flex: 1;
  margin: 0;
  font-size: 11px;
  line-height: 1.15;
}

.schedule-footer p span {
  color: var(--muted);
}

.details-button {
  padding: 0;
  color: var(--leaf);
  background: transparent;
  font-size: 12px;
}

